<?php require 'inc.php';$mon=$_GET['m']??date('Y-m');$fin=$_SESSION['role']==='finance';
if(post()&&$fin){$r=calc($mon,$_POST['m'])[0];if($r['net']>0&&!q('SELECT 1 FROM payment WHERE member_id=? AND pay_month=?',[$r['member_id'],$mon])->fetch())
 q('INSERT INTO payment(member_id,paid_by,pay_month,gross_amount,deductions,net_amount,paid_date) VALUES(?,?,?,?,?,?,CURDATE())',[$r['member_id'],$_SESSION['uid'],$mon,$r['gross'],$r['ded'],$r['net']]);flash('Payment recorded.','payments.php?m='.$mon);}
start('Farmer payments');?><div class="card"><form class="row" method="get"><div><label>Month</label><input type="month" name="m" value="<?=e($mon)?>"></div><button>Show</button></form>
<small>Payment = accepted litres x grade price (A: UGX <?=PRICE_A?>, B: UGX <?=PRICE_B?>) minus feed and drugs taken on credit. <?=$fin?'':'Only the Finance Officer can approve payments.'?></small></div>
<div class="card wrap"><table><tr><th>Farmer</th><th>Litres accepted</th><th>Gross</th><th>Deductions</th><th>Net (UGX)</th><th>Status</th></tr><?php foreach(calc($mon) as $r){$p=q('SELECT paid_date FROM payment WHERE member_id=? AND pay_month=?',[$r['member_id'],$mon])->fetch();
echo '<tr><td>'.e($r['full_name']).'</td><td>'.$r['litres'].'</td><td>'.n($r['gross']).'</td><td>'.n($r['ded']).'</td><td>'.n($r['net']).'</td><td>'.($p?'<span class="tag ok">Paid '.$p['paid_date'].'</span>':($fin&&$r['net']>0?'<form method="post"><input type="hidden" name="m" value="'.$r['member_id'].'"><button>Approve and pay</button></form>':'<span class="tag">Due</span>')).'</td></tr>';}?></table></div><?php done();
